    },
    {
      "word": "空間",
      "reason": "空間は空洞が指すものの上位概念であり、共に用いることは少なく、固定されたコロケーションではない。"
    },
    {
      "word": "開口部",
      "reason": "開口部は空洞の一部を表すが、通常「空洞を開口部」のように一緒に使われることはない。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "作る",
    "reason": "空洞を「作る」は人工的に作り出す場合に限られるが、自然に生じる空洞には「できる」や「生じる」が自然であり、「作る」は通常のコロケーションではない。"
  },
  "cloze_distractors": [
    {
      "word": "穴",
      "reason": "穴は一般用語で、歯科では空洞が専門的に用いられるため、意味の範囲が異なる。"
    },
    {
      "word": "隙間",
      "reason": "隙間は細長いすきまを指し、歯内部の空間（空洞）とは形状が異なる。"
    },
    {
      "word": "くぼみ",
      "reason": "くぼみは表面のへこみであり、内部の空洞を指すのは不適切。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は空洞を食べた。",
      "reason": "動詞「食べる」は食物に用いるが、空洞は食物ではないため、意味的な選択制限に違反している。"
    },
    {
      "sentence": "空洞がとても美しい。",
      "reason": "「空洞」を物理的に美しいと評価する用法は一般的ではなく、使用域（register）として不自然。実際には「景色が美しい」など別の語を使う。"
    },
    {
      "sentence": "この本は空洞です。",
      "reason": "本は物理的に空洞ではないため、字義通りの空洞を当てはめるのは統語的に正しくても意味的に誤り。比喩としても通常「内容が空洞」と言う。"
    }
  ],
  "spot_incorrect": {
