    },
    {
      "word": "中空",
      "type": "synonym",
      "reason": "内部が空であることを表し、空洞の定義と合致する。"
    },
    {
      "word": "充実",
      "type": "antonym",
      "reason": "中身が満たされている状態で、空洞の「空っぽ」という特徴と反対。"
    },
    {
      "word": "実質",
      "type": "antonym",
      "reason": "実体や中身があることを意味し、空洞の空虚さと対立する。"
    }
  ],
  "particle_candidates": {
    "sentence": "この岩の内部には大きな空洞（ ）ある。",
